import{_ as a,o as i,c as t,a1 as s}from"./chunks/framework.C5u0ZYB0.js";const u=JSON.parse('{"title":"aquilifer-types","description":"","frontmatter":{},"headers":[],"relativePath":"docs/aquilifer-types.md","filePath":"docs/aquilifer-types.md","lastUpdated":1790671331000}'),o={name:"docs/aquilifer-types.md"};function r(n,e,l,h,p,c){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="aquilifer-types" tabindex="-1">aquilifer-types <a class="header-anchor" href="#aquilifer-types" aria-label="Permalink to &quot;aquilifer-types&quot;">​</a></h1><p>A companion package: TypeScript types for <code>window.aquilifer</code>, so a website integrating Aquilifer gets full typing without hand-copying shapes from <a href="/projects/aquilifer/docs/api">the page-facing API docs</a>. Published on npm; source lives at <a href="https://github.com/On0n0k1/aquilifer-types" target="_blank" rel="noreferrer">github.com/On0n0k1/aquilifer-types</a>.</p><h2 id="installing-it" tabindex="-1">Installing it <a class="header-anchor" href="#installing-it" aria-label="Permalink to &quot;Installing it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aquilifer-types</span></span></code></pre></div><p>Its types are hand-ported from this repo&#39;s own <code>lib/public-api.ts</code> and kept in sync with it. See the <a href="https://github.com/On0n0k1/aquilifer-types#readme" target="_blank" rel="noreferrer">package&#39;s own README</a> for usage examples; the shapes it exports match what <a href="/projects/aquilifer/docs/api">the page-facing API</a> and its <a href="/projects/aquilifer/docs/generic-api">generic</a>, <a href="/projects/aquilifer/docs/anthropic-api">Anthropic Claude</a>, and <a href="/projects/aquilifer/docs/openai-compatible-api">OpenAI-compatible</a> sub-pages document.</p><h2 id="what-it-ships" tabindex="-1">What it ships <a class="header-anchor" href="#what-it-ships" aria-label="Permalink to &quot;What it ships&quot;">​</a></h2><ul><li>The <code>window.aquilifer</code> type declaration itself, plus every type it depends on (across <a href="/projects/aquilifer/docs/api">the page-facing API</a> and its <a href="/projects/aquilifer/docs/generic-api">generic</a>, <a href="/projects/aquilifer/docs/anthropic-api">Anthropic Claude</a>, and <a href="/projects/aquilifer/docs/openai-compatible-api">OpenAI-compatible</a> sub-pages).</li><li>The provider-specific request/response/stream types, derived from the official <code>@anthropic-ai/sdk</code> and <code>openai</code> packages so they track each provider&#39;s own API shape rather than a hand-maintained copy.</li><li>Two small runtime helpers: <code>getAquilifer()</code> (returns <code>window.aquilifer</code> if present, <code>undefined</code> otherwise) and <code>isAquiliferAvailable()</code> (the same check as a boolean). Small enough that there&#39;s exactly one sane behavior for each, nothing to get wrong in a first release.</li><li>Zero runtime cost for the types themselves: everything is erased at compile time, the same way Aquilifer&#39;s own extension code only ever <code>import type</code>s from the official provider SDKs.</li></ul><h2 id="what-it-won-t-ship-yet" tabindex="-1">What it won&#39;t ship yet <a class="header-anchor" href="#what-it-won-t-ship-yet" aria-label="Permalink to &quot;What it won&#39;t ship yet&quot;">​</a></h2><ul><li>A fallback-pattern helper (see <a href="/projects/aquilifer/docs/api#using-aquilifer-as-a-fallback">Using Aquilifer as a fallback</a>). Nobody&#39;s built a real fallback integration against Aquilifer yet, and this needs real usage to design against rather than guessing upfront and risking a breaking change later.</li><li>Any backend or server code. <code>window.aquilifer</code> only exists inside a browser tab with the extension installed, so a package aimed at server code would be solving a problem that doesn&#39;t exist here.</li></ul><h2 id="which-package-to-install" tabindex="-1">Which package to install <a class="header-anchor" href="#which-package-to-install" aria-label="Permalink to &quot;Which package to install&quot;">​</a></h2><p><strong><a href="https://www.npmjs.com/package/aquilifer-types" target="_blank" rel="noreferrer"><code>aquilifer-types</code></a></strong> — published on npm, and the one this page documents.</p><p>There is also a package published under the bare name <strong><code>aquilifer</code></strong>, with no <code>-types</code> suffix. <strong>That one is not this package and isn&#39;t meant to be installed</strong>: it&#39;s a minimal stub holding the name against squatting, with no types and no code in it. npm has no way to reserve a name without publishing something under it, which is the only reason it exists.</p><p>The extension itself isn&#39;t on npm under either name — it ships through <a href="https://chromewebstore.google.com/detail/aquilifer/aflcbgcgkaenbkecookfmndjgmgdancg" target="_blank" rel="noreferrer">the Chrome Web Store</a>. Installing <code>aquilifer-types</code> gives a site&#39;s own code the types for <code>window.aquilifer</code>; it neither installs the extension nor requires visitors to have it.</p>',13)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
